def text_lowercase_underscore(text):
    if not text:
        return False

    for char in text:
        if not (char.islower() or char == '_'):
            return False

    # Check if there's at least one underscore
    if '_' not in text:
        return False

    # Check that underscore is not at the beginning or end
    if text.startswith('_') or text.endswith('_'):
        return False

    # Check that there are no consecutive underscores
    if '__' in text:
        return False

    # Check that each part separated by underscore contains at least one letter
    parts = text.split('_')
    for part in parts:
        if not part or not part.islower():
            return False

    return True

def octagonal(n):
