def is_octagonal(num):
    # Solve the equation num = n * (3n - 2) for n
    # 3n^2 - 2n - num = 0
    # Using quadratic formula: n = (2 + sqrt(4 + 12*num)) / 6

    discriminant = 4 + 12 * num
    n = (2 + (discriminant ** 0.5)) / 6

    # Check if n is a positive integer
    return n > 0 and n.is_integer()

