def dif_Square(n):
    if n % 2 == 1:
        return True

    while n % 2 == 0:
        n //= 2

    for i in range(3, int(n**0.5) + 1, 2):
        count = 0
        while n % i == 0:
            count += 1
            n //= i
        if count % 2 == 1:
            return False

    return n == 1 or n % 4 == 1

