def sequence(n):
    if n <= 0:
        raise ValueError("Input must be a positive integer")

    if n <= 2:
        return 1

    # Initialize the sequence with the first two elements
    seq = [0, 1, 1]  # 0-indexed, so we add a 0 at the beginning

    for i in range(3, n + 1):
        # The next number is the sum of the positions at seq[seq[i-1]] and seq[seq[i-2]]
        seq.append(seq[seq[i-1]] + seq[seq[i-2]])

    return seq[n]

