def search(arr):
    n = len(arr)

    # Handle edge cases
    if n == 1:
        return arr[0]
    if arr[0] != arr[1]:
        return arr[0]
    if arr[n-1] != arr[n-2]:
        return arr[n-1]

    # Binary search
    left, right = 0, n-1
    while left <= right:
        mid = (left + right) // 2

        # If mid is the single element
        if arr[mid] != arr[mid-1] and arr[mid] != arr[mid+1]:
            return arr[mid]

        # If mid is at even index and same as next element
        # or mid is at odd index and same as previous element
        if (mid % 2 == 0 and arr[mid] == arr[mid+1]) or (mid % 2 == 1 and arr[mid] == arr[mid-1]):
            left = mid + 1
        else:
            right = mid - 1

    return -1  # Not found

