def sum_common_divisors(a, b):
    # Find the minimum of the two numbers
    min_num = min(a, b)

    # Find the GCD of the two numbers
    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x

    g = gcd(a, b)

    # Find all divisors of the GCD
    divisors = []
    for i in range(1, g + 1):
        if g % i == 0:
            divisors.append(i)

    # Return the sum of all common divisors
    return sum(divisors)

