    # Calculate the expected sum
    expected_sum = n * (n**2 + 1) // 2

    # Check rows
    for row in matrix:
        if sum(row) != expected_sum:
            return False

    # Check columns
    for j in range(n):
        if sum(matrix[i][j] for i in range(n)) != expected_sum:
            return False

    # Check main diagonal
    if sum(matrix[i][i] for i in range(n)) != expected_sum:
        return False

    # Check other diagonal
