def count_binary_seq(n):
    # For each possible sum k from 0 to n, count sequences where first n bits sum to k
    # and last n bits also sum to k
    total_count = 0

    for k in range(n+1):
        # Number of ways to choose k positions out of n for 1s in the first half
        first_half_ways = binomial_coefficient(n, k)
        # Number of ways to choose k positions out of n for 1s in the second half
        second_half_ways = binomial_coefficient(n, k)

        # Multiply to get total combinations for this particular sum k
        total_count += first_half_ways * second_half_ways

