def binomial_coefficient(n, k):
    """Calculate n choose k"""
    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1

    result = 1
    for i in range(1, k + 1):
        result = result * (n - (i - 1)) // i

    return result

