def set_left_most_unset_bit(n):
    if n == 0:
        return 1

    # Find the position of the leftmost unset bit
    position = 0
    temp = n

    # Find the position of the most significant bit
    while temp:
        position += 1
        temp >>= 1

    # Check each bit from left to right
    for i in range(position - 1, -1, -1):
        # If the bit at position i is unset (0)
        if not (n & (1 << i)):
            # Set this bit
            return n | (1 << i)

    # If all bits are set, return the number as is
    return n

