def get_total_number_of_sequences(m, n):
    # Initialize a 2D DP array where dp[i][j] represents the number of sequences
    # of length i ending with value j
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Base case: sequences of length 1
    for j in range(1, m + 1):
        dp[1][j] = 1

    # Fill the DP array
    for i in range(2, n + 1):
        for j in range(1, m + 1):
            # For each ending value j, count sequences where the previous value
            # is at most j/2 (integer division)
            for k in range(1, j // 2 + 1):
                dp[i][j] += dp[i-1][k]

    # Sum up all possible sequences of length n
    return sum(dp[n])

def get_total_number_of_sequences(n, m):
    # Initialize a 2D DP array where dp[i][j] represents the number of sequences
    # of length i ending with value j
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Base case: sequences of length 1
    for j in range(1, m + 1):
        dp[1][j] = 1

    # Fill the DP array
    for i in range(2, n + 1):
        for j in range(1, m + 1):
            # For each ending value j, consider all possible previous values k
            # where j <= 2*k
            for k in range((j + 1) // 2, m + 1):
                dp[i][j] += dp[i-1][k]

    # Sum up all sequences of length n
    return sum(dp[n])

