    # Extend the array by concatenating it k times
    extended_arr = arr * k

    # Kadane's algorithm to find maximum subarray sum
    max_so_far = float('-inf')
    max_ending_here = 0

    for i in range(len(extended_arr)):
        max_ending_here = max_ending_here + extended_arr[i]
        if max_so_far < max_ending_here:
            max_so_far = max_ending_here
        if max_ending_here < 0:
            max_ending_here = 0

    return max_so_far

def get_max_sum(n):
    memo = {}

    def dp(n):
        if n <= 0:
            return 0

        if n in memo:
            return memo[n]

        memo[n] = max(dp(n//2) + dp(n//3) + dp(n//4) + dp(n//5), n)
        return memo[n]

    return dp(n)

def get_max_sum(n, memo=None):
    if memo is None:
        memo = {}

    if n in memo:
        return memo[n]

    if n <= 1:
        return n

    max_value = n
    for divisor in [2, 3, 4, 5]:
        split_value = get_max_sum(n // divisor, memo) + get_max_sum(n - (n // divisor), memo)
        max_value = max(max_value, split_value)

    memo[n] = max_value
    return max_value

