def next_smallest_palindrome(n):
    n_str = str(n + 1)
    length = len(n_str)

    # Check if the number is already a palindrome
    if n_str == n_str[::-1]:
        return n + 1

    # For odd length
    if length % 2 == 1:
        left_half = n_str[:length//2]
        mid = n_str[length//2]
        candidate = left_half + mid + left_half[::-1]
        if int(candidate) > n:
            return int(candidate)

        # Increment the middle digit or left half
        if mid < '9':
            mid = str(int(mid) + 1)
            return int(left_half + mid + left_half[::-1])
        else:
            left_half = str(int(left_half + '0') + 1)
            return int(left_half[:-1] + '0' + left_half[:-1][::-1])

    # For even length
    else:
        left_half = n_str[:length//2]
        candidate = left_half + left_half[::-1]
        if int(candidate) > n:
            return int(candidate)

        # Increment the left half
        left_half = str(int(left_half) + 1)
        return int(left_half + left_half[::-1])

