def flip(arr, k):
    left = 0
    while left < k:
        arr[left], arr[k] = arr[k], arr[left]
        left += 1
        k -= 1
    return arr

def find_max_index(arr, n):
    max_index = 0
    for i in range(1, n):
        if arr[i] > arr[max_index]:
            max_index = i
    return max_index

def pancake_sort(arr):
    n = len(arr)
    curr_size = n

    while curr_size > 1:
        max_index = find_max_index(arr, curr_size)

        if max_index != curr_size - 1:
            flip(arr, max_index)
            flip(arr, curr_size - 1)

        curr_size -= 1

    return arr

def pancake_sort(arr):
    n = len(arr)

    for curr_size in range(n, 1, -1):
        # Find index of the maximum element in arr[0..curr_size-1]
        max_idx = arr.index(max(arr[0:curr_size]))

        # Move the maximum element to the end of the current subarray
        if max_idx != curr_size - 1:
            # Flip arr[0...max_idx] to bring the maximum element to the beginning
            if max_idx > 0:
                arr[:max_idx+1] = reversed(arr[:max_idx+1])

            # Flip arr[0...curr_size-1] to bring the maximum element to the end
            arr[:curr_size] = reversed(arr[:curr_size])

    return arr

