def sumofFactors(n):
    factors_sum = 0

    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            # If i is even, add it to the sum
            if i % 2 == 0:
                factors_sum += i

            # Check for the other factor (n/i)
            if i != n // i:  # Avoid counting the same factor twice for perfect squares
                if (n // i) % 2 == 0:  # If n/i is even
                    factors_sum += n // i

    return factors_sum

