def sum_Of_Subarray_Prod(nums):
    n = len(nums)
    total_sum = 0

    for i in range(n):
        for j in range(i, n):
            product = 1
            for k in range(i, j + 1):
                product *= nums[k]
            total_sum += product

    return total_sum

