def divisible_by_digits(startnum, endnum):
    result = []

    for num in range(startnum, endnum + 1):
        is_divisible = True

        # Convert number to string to iterate through its digits
        num_str = str(num)

        for digit in num_str:
            # Skip digit 0 as division by zero is undefined
            if digit == '0':
                is_divisible = False
                break

            # Check if num is divisible by the current digit
            if num % int(digit) != 0:
                is_divisible = False
                break

        if is_divisible:
            result.append(num)

    return result

