def find_sum(lst):
    unique_elements = set()
    repeated_elements = set()

    for item in lst:
        if item in unique_elements:
            repeated_elements.add(item)
        else:
            unique_elements.add(item)

    non_repeated = unique_elements - repeated_elements
    return sum(non_repeated) + sum(repeated_elements)

