def max_sum_list(lists):
    if not lists:
        return None

    max_sum = float('-inf')
    max_list = None

    for lst in lists:
        current_sum = sum(lst)
        if current_sum > max_sum:
            max_sum = current_sum
            max_list = lst

    return max_list

